(()=>{
const root=document.querySelector('#monte-seu-kit');
const colors={'Branco':'#f4f1e9','Rose':'#c7a1a8','Rosa Claro':'#e6c7c5','Cinza Claro':'#c4c5c1','Marfim':'#e9dfc5','Azul Claro':'#b4cad5','Verde':'#8c9b83','Marrom':'#877064','Cinza Escuro':'#686c6b','Bege':'#c9b99f'};
const pieces=[{key:'left',name:'Fronha esquerda',handle:'lencol-sem-elastico-copia',color:'Branco',on:true},{key:'right',name:'Fronha direita',handle:'lencol-sem-elastico-copia',color:'Branco',on:true},{key:'sheet',name:'Lençol com elástico',handle:'lencol-c-elastico-solteiro',color:'Marfim',on:true},{key:'top',name:'Lençol de cima',handle:'lencol-sem-elastico',color:'Branco',on:false},{key:'duvet',name:'Capa de duvet',handle:'capa-de-edredom',color:'Bege',on:false}];
let active='left',size='Queen',catalog=[];const q=s=>root.querySelector(s),sizeName=s=>(s||'').split('|')[0].trim();
function product(p){return catalog.find(x=>x.handle===p.handle)}
function variant(p,color=p.color){return product(p)?.variants.find(v=>v.option1===color&&(!v.option2||sizeName(v.option2)===size))}
function choose(key){if(!catalog.length)return;active=key;render()}
function render(){const p=pieces.find(x=>x.key===active);q('#kit-size').value=size;pieces.forEach(x=>{root.style.setProperty('--kit-'+x.key,colors[x.color]||'#eee');const layer=q('[data-layer="'+x.key+'"]');layer.classList.toggle('omitted',!x.on);layer.classList.toggle('selected',x.key===active);layer.setAttribute('aria-pressed',String(x.key===active));layer.setAttribute('aria-label',x.name+': '+x.color+(x.on?'':', não incluída'));});
q('#kit-pieces').innerHTML=pieces.map(x=>`<button class="kit-piece ${x.key===active?'active':''}" data-piece="${x.key}" aria-pressed="${x.key===active}"><i style="background:${colors[x.color]}"></i><span>${esc(x.name)}<small>${x.on?esc(x.color):'Não incluído'}</small></span><span>${x.on?'✓':'+'}</span></button>`).join('');q('#kit-active-name').textContent=p.name;q('#kit-color-name').textContent=p.color;q('#kit-include').checked=p.on;q('#kit-include-label').textContent='Incluir '+p.name.toLowerCase();
q('#kit-colors').innerHTML=product(p).options[0].values.map(c=>{const v=variant(p,c);return `<button class="kit-color ${c===p.color?'active':''}" style="--swatch:${colors[c]||'#eee'}" data-color="${esc(c)}" aria-label="${esc(c)}${v?.available?'':' — indisponível'}" aria-pressed="${c===p.color}" title="${esc(c)}" ${v?.available?'':'disabled'}><span></span></button>`}).join('');
const v=variant(p);q('#kit-piece-price').textContent=v?money(v.price)+' / peça':'Combinação indisponível';q('#kit-measures').textContent=v?.option2?.includes('|')?'Medidas: '+v.option2.split('|')[1].trim()+' cm':p.key==='left'||p.key==='right'?'Fronha 50 × 70 cm. Enchimento não incluído.':'';
const chosen=pieces.filter(x=>x.on),invalid=chosen.filter(x=>!variant(x)?.available),total=chosen.reduce((sum,x)=>sum+Number(variant(x)?.price||0),0);q('#kit-total').textContent=money(total);q('#kit-count').textContent=chosen.length+' peças selecionadas';q('#kit-add').disabled=!chosen.length||!!invalid.length;q('#kit-feedback').textContent=invalid.length?'Indisponível: '+invalid.map(x=>x.name).join(', ')+'. Escolha outra cor ou tamanho.':!chosen.length?'Selecione pelo menos uma peça.':'Peças avulsas combinadas por você. Sem desconto de kit aplicado.';
q('#kit-summary').innerHTML=chosen.map(x=>`<div><span>${esc(x.name)} · ${esc(x.color)}</span><span>${variant(x)?money(variant(x).price):'Indisponível'}</span></div>`).join('');
q('#kit-photo').src=v?.featured_image?.src||product(p).localImage;q('#kit-photo').alt=p.name+' — '+p.color;q('#kit-product-link').href='https://cozybedhome.com/products/'+p.handle+(v?'?variant='+v.id:'');
}
root.addEventListener('click',e=>{const piece=e.target.closest('[data-piece]');if(piece)choose(piece.dataset.piece);const layer=e.target.closest('[data-layer]');if(layer)choose(layer.dataset.layer);const color=e.target.closest('[data-color]');if(color&&!color.disabled){pieces.find(x=>x.key===active).color=color.dataset.color;render()}const preset=e.target.closest('[data-preset]');if(preset){const palette={natural:['Branco','Branco','Marfim','Branco','Bege'],sage:['Marfim','Verde','Verde','Marfim','Bege'],rose:['Rosa Claro','Rose','Branco','Rosa Claro','Bege']}[preset.dataset.preset];pieces.forEach((x,i)=>{if(variant(x,palette[i])?.available)x.color=palette[i]});render()}});
root.querySelectorAll('[data-layer]').forEach(el=>el.addEventListener('keydown',e=>{if(e.key==='Enter'||e.key===' '){e.preventDefault();choose(el.dataset.layer)}}));
q('#kit-size').onchange=e=>{size=e.target.value;render()};q('#kit-include').onchange=e=>{pieces.find(x=>x.key===active).on=e.target.checked;render()};q('#kit-reset').onclick=()=>{size='Queen';pieces.forEach((x,i)=>{x.color=['Branco','Branco','Marfim','Branco','Bege'][i];x.on=i<3});active='left';render()};
q('#kit-add').onclick=()=>{const chosen=pieces.filter(x=>x.on);if(!chosen.length||chosen.some(x=>!variant(x)?.available))return;chosen.forEach(p=>{const v=variant(p),prod=product(p),item=cart.find(x=>x.id===v.id);if(item)item.qty++;else cart.push({id:v.id,productId:prod.id,title:short(prod),variant:v.title,price:v.price,image:prod.localImage,qty:1})});save();openCart()};
fetch('products.json').then(r=>{if(!r.ok)throw Error();return r.json()}).then(data=>{catalog=data;if(pieces.some(p=>!product(p)))throw Error();q('#kit-size').innerHTML=product(pieces[2]).options[1].values.map(s=>`<option value="${esc(sizeName(s))}">${esc(sizeName(s))}</option>`).join('');q('#kit-loading').hidden=true;q('#kit-controls').hidden=false;render()}).catch(()=>{q('#kit-loading').textContent='Não foi possível carregar o montador. Recarregue a página ou fale com a gente pelo WhatsApp.'});
})();
